// Utility Studio Workspace: SAP-style transactions over the meter-to-cash engine (Astra's design,
// prototypes/utility-studio). Records, amounts, statuses and VEE results come from the engine through EngineM2C;
// nothing here invents a record. Query context (what you executed) is session state, kept apart from engine data.
import {escapeText as e} from './customer-view.js';
import {scorecardMarkup} from './worklists.js';

export const TRANSACTIONS=[
 ['Worklists','exceptions','Clarification Case List'],
 ['Worklists','vee','Resolve Implausible Meter Readings'],
 ['Display','billing-query','Display Billing'],
 ['Display','read-query','Display Meter Reading Results']
];
export const CATEGORIES=['My Assigned Cases','AMP','Bill Correction','Bill Print Errors','Billing Errors','Billing Outsorts','Billing- see IT Supp','Budget Bill Cases','Invoice Errors','Invoice Outsorts','Low Income Process','MR Implausibles','Meter Read Follow-Up','Field Work'];
const MISSING=['COMM_FAIL','NO_ACCESS','NO_READ','CONSECUTIVE_ESTIMATES'];
const VALUE_QUEUES=['VEE_REVIEW','SUPERVISOR'];
const SUBSTATUS={queued:['001','Awaiting pickup'],assigned:['002','In analyst review'],escalated:['003','Supervisor review'],field:['010','Field visit'],held:['004','Held'],resolved:['009','Completed']};

// The clarification category of an engine case: the engine's own when it sends one, otherwise derived from its queue
// and exception type. Categories with no engine meaning stay empty rather than showing invented cases.
export function categoryOf(row){
 if(row.category)return row.category;
 if(row.queue==='FIELD')return 'Field Work';
 if(row.type==='RATE_CLASS')return 'Billing Errors';
 if(['HIGH_BILL','BILL_CREDIT'].includes(row.type))return 'Billing Outsorts';
 if(MISSING.includes(row.type)||row.queue==='ESTIMATION')return 'Meter Read Follow-Up';
 if(VALUE_QUEUES.includes(row.queue))return 'MR Implausibles';
 return 'MR Implausibles';
}
export function caseStatus(row){if(row.resolvedAt)return 'Completed';return row.assignee&&row.assignee!=='RPA'?'Assigned':'Open';}
export function substatus(row){if(row.resolvedAt)return SUBSTATUS.resolved;if(row.queue==='FIELD')return SUBSTATUS.field;if(row.queue==='SUPERVISOR')return SUBSTATUS.escalated;return row.assignee?SUBSTATUS.assigned:SUBSTATUS.queued;}
export function matchesCategory(row,category){return category==='My Assigned Cases'?row.owner==='you'||row.assignee==='you':categoryOf(row)===category;}

// Workspace routes: #/workspace/<transaction>, #/workspace/case/<id>, #/workspace/billing/<installation>/<screen>,
// #/workspace/reads/<readId>[/<screen>], #/workspace/field-order/<orderId>.
export function parseWorkspaceRoute(hash){
 const parts=String(hash||'').replace(/^#\/workspace\/?/,'').split('/').filter(Boolean).map(decodeURIComponent);
 const [head='exceptions',a=null,b=null,c=null]=parts,item=c?{item:c}:{};
 if(head==='case')return {tx:'exceptions',caseId:a};
 if(head==='billing')return {tx:'billing',record:a,screen:b||'orders',...item};
 if(head==='reads')return {tx:'reads',record:a,screen:b||'reads',...item};
 if(head==='field-order')return {tx:'field-order',record:a};
 if(head==='statistics')return {tx:'statistics'};
 return {tx:TRANSACTIONS.some(t=>t[1]===head)?head:'exceptions'};
}
export function workspaceHash(r){
 if(r.caseId)return '#/workspace/case/'+encodeURIComponent(r.caseId);
 const item=r.item?'/'+encodeURIComponent(r.item):'';
 if(r.tx==='billing')return `#/workspace/billing/${encodeURIComponent(r.record)}/${r.screen||'orders'}${item}`;
 if(r.tx==='reads')return `#/workspace/reads/${encodeURIComponent(r.record)}${(r.screen&&r.screen!=='reads')||item?'/'+(r.screen||'reads'):''}${item}`;
 if(r.tx==='field-order')return '#/workspace/field-order/'+encodeURIComponent(r.record);
 if(r.tx==='statistics')return '#/workspace/statistics';
 return '#/workspace/'+(r.tx||'exceptions');
}

const sapTable=(heads,rows,none='No entries.')=>`<div class="sap-table"><table><thead><tr><th style="width:23px"></th>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td class="sap-row-no">${i+1}</td>${r.map(x=>`<td>${x==null||x===''?'—':x}</td>`).join('')}</tr>`).join(''):`<tr><td></td><td colspan="${heads.length}">${none}</td></tr>`}</tbody></table></div>`;
const sapLink=(text,screen,item='')=>`<button type="button" class="sap-link" data-ws="screen" data-screen="${screen}"${item?` data-item="${e(item)}"`:''}>${e(text)}</button>`;
const sapField=(label,value,link='')=>`<div class="sap-field"><label>${e(label)}</label>${link||`<span class="sap-input" title="${value==null?'':e(String(value))}">${value==null||value===''?'—':e(String(value))}</span>`}</div>`;
const SCREENS={orders:'Billing view of installation',periods:'Billing view of installation',documents:'Billing view of installation',document:'Display Billing Document',invoice:'Display Print Document',contract:'Display Contract',installation:'Display Installation',reads:'Display Meter Reading Results',device:'Display Device and Register'};
const FO_LABELS={orderType:'Order',shortText:'Description',plannerGroup:'PlannerGrp',plant:'Planning plant',workCenter:'Mn.wk.ctr',responsible:'Person Resp.',activityType:'PMActType',startDate:'Bsc start',finishDate:'Basic fin.',priority:'Priority',longText:'Longtext',operation:'Operation text',duration:'Duration (minutes)',contactName:'Contact name',contactPhone:'Telephone',accessNotes:'Instructions'};
const FO_TABS=[['header','HeaderData'],['operations','Operations'],['components','Components'],['partner','Partner']];
const validDay=x=>{const t=Date.parse(x+'T00:00:00Z');return /^\d{4}-\d{2}-\d{2}$/.test(x)&&Number.isFinite(t)&&new Date(t).toISOString().slice(0,10)===x;};
const money=n=>n==null?'—':new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(n);
const num=(v,d=3)=>v==null?'—':new Intl.NumberFormat('en-CA',{maximumFractionDigits:d}).format(v);
const LOCAL_DAY=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}),LOCAL_HM=new Intl.DateTimeFormat('en-GB',{timeZone:'America/Toronto',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
const day=iso=>!iso?'—':String(iso).length>10&&!/T00:00:00(\.0+)?Z$/.test(iso)?LOCAL_DAY.format(new Date(iso)):String(iso).slice(0,10); // a midnight-UTC stamp is a date
const hm=iso=>iso&&String(iso).length>10?LOCAL_HM.format(new Date(iso)):'';
const btn=(label,act,extra='')=>`<button type="button" data-ws="${act}" ${extra}>${label}</button>`;
const field=(label,value,extra='')=>`<div class="gui-field"><span>${e(label)}</span><span class="gui-value ${extra}" title="${value==null?'':e(String(value))}">${value==null||value===''?'—':e(String(value))}</span></div>`;
const group=(title,body,extra='')=>`<fieldset class="gui-group ${extra}"><legend>${e(title)}</legend>${body}</fieldset>`;

export function installWorkspace({getClient,toast=()=>{},onShowPremise=()=>{},onProcess=()=>{},onWatch=()=>{},root=document.getElementById('workspace-root')}){
 const client=()=>getClient();
 const ui={route:{tx:'exceptions'},category:'My Assigned Cases',status:'Open',query:'',sort:'age',compact:false,veeStatus:'open',veeUtility:'all',veeQuery:'',filters:false,selected:new Set(),historyOpen:false,queries:{installation:'',read:''},queryError:'',context:{installation:null,read:null},rows:[],veeRows:[],caseView:null,record:null,busy:0,message:'',order:null,orderReturn:null,vocab:null,readOrigin:null};
 // Query context: a record page opens only for the record you executed in this session.
 const has=(kind,id)=>ui.context[kind]===id;
 function go(r){const h=workspaceHash(r);if(location.hash!==h)location.hash=h;else open(h);}
 function header(tx,title=''){
  const groups=[...new Set(TRANSACTIONS.map(t=>t[0]))],current=title||TRANSACTIONS.find(t=>t[1]===tx)?.[2]||'';
  return `<header class="sap-transaction-header ${title?'sap-transaction-classic':''}"><span class="sap-emblem">SAP</span><select id="ws-transaction" aria-label="SAP transaction">${title?`<option value="" selected disabled>${e(title)}</option>`:''}${groups.map(g=>`<optgroup label="${g}">${TRANSACTIONS.filter(t=>t[0]===g).map(([,id,label])=>`<option value="${id}" ${!title&&id===tx?'selected':''}>${label}</option>`).join('')}</optgroup>`).join('')}</select><span class="spacer"></span><small>100</small></header>`;
 }
 function statusbar(text){const m=client();return `<footer class="fiori-status"><span class="sap-square green"></span><span>${e(text)}</span><span class="spacer"></span><label class="ws-asof">Run date <input type="date" id="ws-asof" min="2026-01-01" max="2026-12-31" value="${e(m?.asOf||ui.asOf||'')}"></label><span>Engine data</span></footer>`;}
 function empty(text){return `<section class="fiori-shell">${header(ui.route.tx)}<div class="fiori-empty ws-empty">${text}</div>${statusbar('Workspace')}</section>`;}

 // ---- Clarification Case List ----------------------------------------------------------------------------------
 function caseRows(){const q=ui.query.trim().toLowerCase();return ui.rows.filter(r=>matchesCategory(r,ui.category)&&(ui.status==='All'||(ui.status==='Completed'?!!r.resolvedAt:!r.resolvedAt))&&(!q||`${r.caseId} ${r.label} ${r.address} ${r.accountId} ${r.premiseId}`.toLowerCase().includes(q)));}
 function caseBody(){const rows=caseRows();return rows.length?rows.map(r=>{const [code,text]=substatus(r),done=!!r.resolvedAt;return `<tr class="clarification-row" data-case="${e(r.caseId)}" tabindex="0"><td><span class="clarification-status ${done?'complete':''}"></span></td><td class="${done?'':'overdue-cell'}">${done?'—':r.ageDays+' d'}</td><td>${e(r.caseId)}</td><td>${e(r.icon||'')} ${e(r.label)} · ${e(r.address)}</td><td>${caseStatus(r)}</td><td>${code}</td><td>${e(text)}</td><td>${e(r.queue||'—')}</td><td>Monthly</td><td>UTILSIM</td><td>${e(r.assignee==='you'?'You':r.assignee||'Unassigned')}</td></tr>`;}).join(''):`<tr><td colspan="11" class="fiori-empty">${ui.busy?'Loading cases from the engine…':`No ${ui.status==='Open'?'open ':''}cases in ${e(ui.category)}${ui.query?' match this search':''}.`}</td></tr>`;}
 function casesPage(){const n=caseRows().length;return `<section class="fiori-shell clarification-shell">${header('exceptions')}<div class="clarification-main-toolbar">${btn(ui.compact?'Comfortable layout':'Compact layout','layout')}${btn('Update Clarification Case List','refresh')}${btn('Export list','export-cases')}${btn('Run statistics','statistics')}</div><div class="clarification-layout"><aside class="clarification-sidebar"><div>Billing</div><nav aria-label="Clarification categories">${CATEGORIES.map(c=>`<button data-category="${c}" class="${ui.category===c?'active':''}" ${ui.category===c?'aria-current="page"':''}>${c}${ui.counts&&ui.counts[c]?`<span class="ws-count">${ui.counts[c]}</span>`:''}</button>`).join('')}</nav></aside><section class="clarification-main"><div class="clarification-title">${e(ui.category)}</div><div class="clarification-table-toolbar">${btn(ui.sort==='age'?'Oldest first':'Case number','sort','class="native-tool sort-tool" title="Change sort order"')}<label class="sr-only" for="ws-status">Status</label><select id="ws-status">${['Open','Completed','All'].map(v=>`<option ${ui.status===v?'selected':''}>${v}</option>`).join('')}</select><input type="search" id="ws-query" placeholder="Case, text, account…" value="${e(ui.query)}" aria-label="Find clarification case"><span class="spacer"></span><span id="ws-count">${n} cases</span></div><div class="clarification-table-scroll ${ui.compact?'compact':''}"><table class="clarification-table"><thead><tr><th></th><th>Overdue</th><th>Case</th><th>Clarification Case Text</th><th>Status</th><th>Substatus</th><th>Substatus Text</th><th>Job</th><th>Interval</th><th>Logical system</th><th>Assignee</th></tr></thead><tbody id="ws-cases">${caseBody()}</tbody></table></div></section></div>${statusbar('Clarification Case List')}</section>`;}
 async function loadCounts(){const m=client();if(!m)return;try{const res=await m.post('/process/queue',{status:'open',page:1,pageSize:200},'counts');const n={};for(const r of res.rows||[]){const c=categoryOf(r);n[c]=(n[c]||0)+1;if(r.owner==='you'||r.assignee==='you')n['My Assigned Cases']=(n['My Assigned Cases']||0)+1;}ui.counts=n;if(ui.route.tx==='exceptions'&&!ui.route.caseId)render();}catch(err){if(!err.superseded)ui.counts=null;}}
 async function loadCases(){const m=client();if(!m)return;const ticket=++ui.busy;try{const status=ui.status==='Completed'?'resolved':ui.status==='All'?'all':'open';const res=await m.queue({status,sort:ui.sort==='age'?'age':'created',page:1,pageSize:200,...(ui.category?{category:ui.category}:{})});if(ticket!==ui.busy)return;ui.rows=res.rows||[];ui.total=res.total;ui.asOf=res.asOf;}catch(err){if(!err.superseded)toast('Engine: '+err.message);}finally{if(ticket===ui.busy){ui.busy=0;render();}}}

 // ---- Run statistics: the year's KPIs as of the run date, and VEE against simulation truth ----------------------
 function statisticsPage(){const sum=ui.summary;if(!sum)return empty('Loading run statistics from the engine…');const k=sum.kpis,b=sum.billing||{},rel=sum.reliability||{},pct=x=>x==null?'—':Math.round(x*100)+'%',grid=(rows)=>`<div class="gui-master-grid ws-stats">${rows.map(col=>`<div>${col.map(([l,v])=>field(l,v)).join('')}</div>`).join('')}</div>`;
  const queues=sum.queues.map(q=>`<tr><td>${e(q.label)}</td><td>${q.open}</td><td>${q.aging['0-1']}</td><td>${q.aging['2-3']}</td><td>${q.aging['4-7']}</td><td>${q.aging['8+']}</td><td>${q.oldestDays}</td></tr>`).join('');
  const relRows=Object.entries(rel).map(([u,r])=>`<tr><td>${e(u)}</td><td>${r.interruptions}</td><td>${num(r.customersInterrupted,0)}</td><td>${num(r.customerMinutes,0)}</td><td>${r.saidiMinutes??'—'}</td><td>${num(r.lost,1)} ${e(r.unit)}</td></tr>`).join('');
  return `<section class="fiori-shell gui-case-shell">${header('exceptions','Run Statistics')}<nav class="gui-transaction-toolbar">${btn('‹ Back to List','back')}${btn(ui.scorecard?'Hide VEE scorecard':'VEE scorecard','scorecard')}</nav><div class="gui-case-scroll"><div class="gui-case-content">
   ${group('Meter Reading',grid([[['Reads to date',num(k.reads,0)],['Actual',num(k.actual,0)],['Missing',num(k.missing,0)]],[['Auto-accepted',num(k.autoAccepted,0)],['Flagged by VEE',num(k.flagged,0)],['Estimated',num(k.estimated,0)]]]))}
   ${group('Work Queues',grid([[['Cases opened',num(k.casesOpened,0)],['Resolved',num(k.casesResolved,0)],['Open now',num(k.casesOpen,0)]],[['Field orders',num(k.fieldOrders,0)],['Truck rolls',num(k.truckRolls,0)],['Days to release',k.avgDaysToRelease??'—']]])+`<table class="gui-history-table"><thead><tr><th>Queue</th><th>Open</th><th>0–1 d</th><th>2–3 d</th><th>4–7 d</th><th>8+ d</th><th>Oldest</th></tr></thead><tbody>${queues}</tbody></table>`)}
   ${group('Costs',grid([[['Labour',money(k.costs.labor)],['System',money(k.costs.system)],['Customer experience',money(k.costs.cx)]],[['Meter reading',money(k.costs.reads)],['Total',money(k.costs.total)],['Carrying cost',money(k.carry)]]]))}
   ${b.documents!=null?group('Billing and Collections',grid([[['Billing documents',num(b.documents,0)],['Blocked',num(b.blocked,0)],['Billed',money(b.billed)],['Billing error vs truth',money(b.billingError)]],[['Invoices',num(b.invoices,0)],['Collected',money(b.collected)],['Receivable',money(b.receivable)],['Overdue',money(b.overdue)]]])):''}
   ${relRows?group('Service Interruptions (from the map)',`<table class="gui-history-table"><thead><tr><th>Utility</th><th>Interruptions</th><th>Customers</th><th>Customer-minutes</th><th>SAIDI min</th><th>Use lost</th></tr></thead><tbody>${relRows}</tbody></table>`):''}
   ${group('VEE against Simulation Truth',grid([[['Precision',pct(k.vee.precision)],['Recall',pct(k.vee.recall)]],[['True positives',num(k.vee.truePositives,0)],['False positives',num(k.vee.falsePositives,0)]]])+(ui.scorecard?`<div class="ws-scorecard">${ui.scorecard===true?'<p class="small-note">Scoring VEE…</p>':scorecardMarkup(ui.scorecard)}</div>`:''))}
  </div></div>${statusbar('Run statistics · as of '+sum.asOf)}</section>`;}
 async function loadSummary(){const m=client();if(!m)return;const ticket=++ui.busy;try{const sum=await m.summary();if(ticket!==ui.busy)return;ui.summary=sum;ui.asOf=sum.asOf;}catch(err){if(!err.superseded)toast('Engine: '+err.message);}finally{if(ticket===ui.busy){ui.busy=0;render();}}}

 // ---- Clarification case detail ---------------------------------------------------------------------------------
 function casePage(c){
  const row=c,done=!!c.resolvedAt,[code,text]=substatus(c),category=categoryOf(c),catCode=String(Math.max(1,CATEGORIES.indexOf(category))).padStart(2,'0'),decision=c.decision||{},read=c.read||{},acts=new Set(c.actions||[]);
  const tests=(decision.tests||[]).map(t=>`<tr><td>${e(t.test)}</td><td>${e(t.outcome)}</td><td>${num(t.contribution,3)}</td><td>${e(t.rationale)}</td></tr>`).join('');
  const history=(c.events||[]).map((ev,i)=>`<tr><td>${i+1}</td><td>${day(ev.occurredAt)} ${hm(ev.occurredAt)}</td><td>${e(ev.payload?.icon||'')} ${e(ev.payload?.label||ev.eventType)}</td></tr>`).join('');
  const valueActions=[acts.has('accept')?(c.queue==='BILLING'?btn('<span class="gui-action-check">✓</span> Release billing / invoice outsort','release-outsort','class="gui-yellow" title="Release the blocked bill with a reason"'):btn('<span class="gui-action-check">✓</span> Clarif. Case Completed','accept',`class="gui-yellow" ${done?'disabled':''} title="Release the read as it stands"`)):'',acts.has('estimate')?btn('Estimate &amp; release','estimate','class="gui-yellow"'):'',acts.has('override')?btn('Correct value…','override','class="gui-yellow"'):'',acts.has('escalate')?btn('Escalate','escalate','class="gui-yellow"'):''].join('');
  return `<section class="fiori-shell gui-case-shell" aria-label="Clarification Case Detail">${header('exceptions','Clarification Case Detail')}<nav class="gui-transaction-toolbar" aria-label="Case transactions">${btn('‹ Back to List','back')}${btn('Display Billing','billing-query')}${btn('Show on map','show-map')}${(c.fieldVisits||[]).length?btn('Watch the truck roll','watch'):''}${btn('Activity sequence','trace')}</nav><div class="gui-case-scroll"><div class="gui-case-content"><div class="gui-case-header"><div><div class="gui-field"><span>Clar.Case Cat.</span><span class="gui-code">${catCode}</span><span class="gui-inline-text">${e(category)}</span></div>${field('Clarif. Case',c.caseId)}</div><div>${field('Created on',day(c.createdAt))}${field('Time',hm(c.createdAt))}${field('Created By',c.queue==='BILLING'?'BILLING_RUN':'VEE_BATCH')}</div></div>
   ${group('Master Data',`<div class="gui-master-grid"><div>${field('Contract Acct',c.accountId)}${field('Installation',read.installationId)}${field('Premise',c.premiseId)}</div><div>${field('Address',c.address)}${field('Division',c.commodity)}${field('Device',read.meterId)}</div></div>`)}
   ${group('Clarification Reason',`<div class="gui-field gui-reason"><span>Clarific.Reason</span><span class="gui-code">${e(c.sapValidationCode||c.type)}</span><span class="gui-reason-text">${e(c.label)}</span></div><p class="gui-reason-description">${e(decision.tests?.find(t=>t.contribution>0)?.rationale||'')}</p>${tests?`<table class="gui-history-table ws-tests"><thead><tr><th>VEE test</th><th>Outcome</th><th>Risk</th><th>Rationale</th></tr></thead><tbody>${tests}</tbody></table>`:''}`)}
   ${group('Meter Reading',`<div class="gui-master-grid"><div>${field('Read document',read.id)}${field('Read date',day(read.readAt))}${field('Read status',read.readStatus)}</div><div>${field('Previous register',num(read.previousRegisterValue))}${field('Reported register',num(read.registerValue))}${field('Consumption',read.consumption==null?null:num(read.consumption)+' '+(read.unit||''))}</div></div>`)}
   <div class="gui-primary-actions">${valueActions||'<span class="gui-processing-hint">No engine actions are open on this case.</span>'}</div>
   ${group('Status/lock information',`<div class="gui-status-grid"><div class="gui-status-fields">${field('Last Processing Status',text,'gui-select-display')}${field('Status',done?'Completed':caseStatus(c),'gui-select-display')}${field('Substatus',code)}</div><div class="gui-status-right">${btn('▤ &nbsp; History','history','class="gui-yellow"')}${field('Last Processor',c.owner==='you'||c.assignee==='you'?'You':c.assignee||'Unassigned')}${field('Queue',c.queue)}</div></div>`)}
   ${group('Processing',`<div class="gui-master-grid"><div>${field('Bill impact',money(c.impact))}${field('VEE confidence',c.confidence==null?null:Math.round(c.confidence*100)+'%')}</div><div>${field('Disposition',c.disposition)}${field('Outcome',c.outcome)}</div></div><div class="gui-inline-actions">${studioButtons(c)}</div>`)}
   ${caseWork(c)}
   ${ui.historyOpen?group('Processing History',`<table class="gui-history-table"><thead><tr><th>Step</th><th>When</th><th>Activity</th></tr></thead><tbody>${history}</tbody></table>`,'gui-history'):''}
  </div></div>${statusbar('Clarification case '+c.caseId+' · '+(done?'Completed':caseStatus(c)))}</section>`;
 }
 // Ownership, notes, field service orders and invoice holds: offered only where the engine says the case takes them today.
 function studioButtons(c){const s=new Set(c.studioActions||[]),order=c.order||(c.orders||[])[0],yes=(act,label)=>btn(label,act,'class="gui-yellow"');
  const html=[s.has('assign')&&c.owner!=='you'?yes('assign','Take ownership'):'',s.has('note')?yes('note','Add note'):'',order?yes('open-order',c.order?'Display Field Service Order':'Open Field Service Order'):s.has('order_save')?yes('field-order','Create Field Service Order'):'',s.has('invoice_hold')?yes('hold','Do Not Invoice Account'):s.has('invoice_unhold')?yes('unhold','Remove Invoice Hold'):''].join('');
  return html||`<span class="gui-processing-hint">${c.resolvedAt?'This case is completed.':'Case work lands at 09:00 on the run date, and the engine raised this case later that day. Move the run date to the next day to work it.'}</span>`;}
 function caseWork(c){const notes=c.notes||[],orders=c.order?[{...c.order,shortText:c.order.fields?.shortText}]:c.orders||[],hold=c.invoiceHold;
  return (notes.length?group('Notes',`<table class="gui-history-table"><thead><tr><th>When</th><th>By</th><th>Note</th></tr></thead><tbody>${notes.map(n=>`<tr><td>${day(n.at)} ${hm(n.at)}</td><td>${e(n.by==='you'?'You':n.by||'')}</td><td>${e(n.text)}</td></tr>`).join('')}</tbody></table>`):'')
   +(orders.length?group('Field Service Orders',`<table class="gui-history-table"><thead><tr><th>Order</th><th>Status</th><th>Description</th><th>Field Work case</th></tr></thead><tbody>${orders.map(o=>`<tr><td><button type="button" class="fiori-link" data-ws="open-order" data-order="${e(o.orderId)}">${e(o.orderId)}</button></td><td>${e(o.systemStatus||'')} · ${e(o.stage||'')}</td><td>${e(o.shortText||'')}</td><td>${e(o.caseId||'')}</td></tr>`).join('')}</tbody></table>`):'')
   +(hold?group('Invoice hold',`<div class="gui-master-grid"><div>${field('Contract Acct',hold.accountId)}${field('Held since',day(hold.since))}</div><div>${field('Reason',hold.note)}${field('Held billing documents',(hold.heldDocumentIds||[]).length)}</div></div>`):'');}
 async function loadCase(id){const m=client();if(!m)return;const ticket=++ui.busy;try{const c=await m.caseView(id);if(ticket!==ui.busy)return;ui.caseView=c;ui.asOf=c.asOf;}catch(err){if(!err.superseded){ui.caseView=null;ui.message=err.status===404?`Case ${id} is not in this run.`:err.message;}}finally{if(ticket===ui.busy){ui.busy=0;render();}}}

 // ---- Resolve Implausible Meter Readings ------------------------------------------------------------------------
 function veeRows(){const q=ui.veeQuery.trim().toLowerCase();return ui.veeRows.filter(r=>(ui.veeUtility==='all'||r.commodity===ui.veeUtility)&&(!q||`${r.caseId} ${r.address} ${r.accountId} ${r.meterId||''} ${r.readId}`.toLowerCase().includes(q)));}
 function veeBody(){const rows=veeRows();return rows.length?rows.map(r=>{const done=!!r.resolvedAt,sel=ui.selected.has(r.caseId);return `<tbody class="vee-record ${done?'released':''}"><tr class="vee-main-row"><td><input type="checkbox" data-read-select="${e(r.caseId)}" ${sel?'checked':''} ${done?'disabled':''} aria-label="Select reading ${e(r.readId)}"></td><td><span class="${done?'vee-released':'vee-overdue'}">${done?'Released':`${r.ageDays} Days<br>Overdue`}</span><br>${e(r.readDate)}</td><td><button class="fiori-link" data-ws="open-read" data-case="${e(r.caseId)}">${e(r.meterId||r.registerId)}</button><br><span class="vee-doc-id">${e(r.readId)}</span><br><span>${e(String(r.commodity).toUpperCase())};${e(r.unit||'')}</span></td><td>001<br>${e(r.commodity)} register</td><td><input type="checkbox" disabled aria-label="No additional meter reading reasons"></td><td>${e(r.mruId||'—')}</td><td>Periodic Meter Reading (01)</td><td>${e(r.technology||'')}</td><td>${btn('›','open-read',`data-case="${e(r.caseId)}" class="row-chevron" aria-label="Open ${e(r.readId)}"`)}</td></tr><tr class="vee-detail-row"><td></td><td colspan="8"><div class="vee-line"><span>Independent Validation:</span><div>${e(r.validationText||r.label)}<br>${e(r.sapValidationCode||'')}</div></div><div class="vee-line"><span>Consumption/Demand:</span><div>Current: &nbsp;${num(r.consumption)} ${e(r.unit||'')}<br>Expected: ${num(r.expected)} ${e(r.unit||'')}</div></div></td></tr></tbody>`;}).join(''):`<tbody><tr><td colspan="9" class="fiori-empty">${ui.busy?'Loading meter readings from the engine…':'No meter readings match the selected filters.'}</td></tr></tbody>`;}
 function veePage(){const rows=veeRows(),open=rows.filter(r=>!r.resolvedAt),selected=open.filter(r=>ui.selected.has(r.caseId)).length;return `<section class="fiori-shell vee-shell">${header('vee')}<section class="vee-variant"><div class="vee-variant-line">${btn('Standard <span class="chevron-down"></span>','filters',`aria-expanded="${ui.filters}"`)}<div class="vee-views"><label class="sr-only" for="ws-vee-view">Read status</label><select id="ws-vee-view"><option value="open" ${ui.veeStatus==='open'?'selected':''}>Open</option><option value="resolved" ${ui.veeStatus==='resolved'?'selected':''}>Released</option><option value="all" ${ui.veeStatus==='all'?'selected':''}>All statuses</option></select></div></div><div class="vee-filter-summary">Filtered By: ${ui.veeStatus==='open'?'Open implausible readings':ui.veeStatus==='resolved'?'Released readings':'All readings'}${ui.veeUtility==='all'?'':' · '+e(ui.veeUtility)}</div><div class="vee-filters" ${ui.filters?'':'hidden'}><label>Utility<select id="ws-vee-utility">${[['all','All utilities'],['gas','Gas'],['water','Water'],['electric','Electric']].map(([v,l])=>`<option value="${v}" ${ui.veeUtility===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Device, account or address<input id="ws-vee-query" type="search" value="${e(ui.veeQuery)}" placeholder="Search readings"></label>${btn('Clear filters','clear-vee')}</div></section><div class="vee-list"><div class="vee-list-toolbar"><h2>Meter Readings (<span>${rows.length}</span>)</h2><span class="spacer"></span><span class="vee-selected">${selected?selected+' selected':''}</span>${btn('Create Field Service Order','vee-order',selected===1?'':'disabled title="Select one open reading"')}${btn('Estimate','estimate-reads',selected?'':'disabled')}${btn('Release','release-reads',selected?'':'disabled')}</div><div class="vee-scroll"><table class="vee-table"><thead><tr><th><input type="checkbox" id="ws-select-all" aria-label="Select all open readings" ${selected&&selected===open.length?'checked':''}></th><th>Sched.<br>Reading Date</th><th>Device</th><th>Register</th><th>More MR<br>Reasons</th><th>Meter Reading Unit</th><th>Meter reading reason</th><th>Meter reading type</th><th></th></tr></thead>${veeBody()}</table></div></div>${statusbar('Resolve Implausible Meter Readings')}</section>`;}
 async function loadVee(){const m=client();if(!m)return;const ticket=++ui.busy;try{const rows=[];for(const queue of VALUE_QUEUES){const res=await m.post('/process/queue',{queue,status:ui.veeStatus,page:1,pageSize:200},'vee:'+queue);ui.asOf=res.asOf;rows.push(...(res.rows||[]));}if(ticket!==ui.busy)return;ui.veeRows=rows.filter(r=>!MISSING.includes(r.type)).sort((a,b)=>b.ageDays-a.ageDays||a.caseId.localeCompare(b.caseId));}catch(err){if(!err.superseded)toast('Engine: '+err.message);}finally{if(ticket===ui.busy){ui.busy=0;render();}}}
 async function releaseSelected(type){const m=client(),ids=[...ui.selected];if(!m||!ids.length)return;let done=0;for(const id of ids){try{await m.act(type,id);done++;ui.selected.delete(id);}catch(err){if(!err.superseded){toast(`${id}: ${err.message}`);break;}}}if(done)toast(`${done} reading${done>1?'s':''} ${type==='estimate'?'estimated and released':'released'} on ${m.asOf}.`);loadVee();}

 // ---- Display Billing / Display Meter Reading Results: query first, then the record ------------------------------
 function queryPage(kind){const isBill=kind==='installation',tx=isBill?'billing-query':'read-query',label=isBill?'Installation':'Meter reading document',value=ui.queries[kind];return `<section class="fiori-shell sap-query-shell">${header(tx)}<form class="sap-query" id="ws-query-form" data-kind="${kind}"><div class="sap-query-row"><label for="ws-query-input">${label}</label><input id="ws-query-input" name="q" value="${e(value)}" autocomplete="off" spellcheck="false" placeholder="${isBill?'Installation number':'Read document id'}">${btn('F4','f4',`data-kind="${kind}" title="Possible entries" aria-label="Possible entries for ${label}"`)}<button type="submit" class="sap-execute">Execute</button></div>${ui.queryError?`<p class="sap-query-error" role="alert">${e(ui.queryError)}</p>`:''}<div id="ws-f4"></div></form>${statusbar(isBill?'Display Billing':'Display Meter Reading Results')}</section>`;}
 async function execute(kind,raw){const id=String(raw||'').trim();ui.queries[kind]=id;ui.queryError='';if(!id){ui.queryError=`Enter ${kind==='installation'?'an installation':'a meter reading document'}.`;render();return;}const m=client();if(!m)return;try{if(kind==='installation'){ui.bill=await m.installation(id);ui.context.installation=id;go({tx:'billing',record:id,screen:'orders'});}else{ui.readDoc=await m.readDocument(id);ui.context.read=id;ui.readOrigin=null;go({tx:'reads',record:id});}}catch(err){if(err.superseded)return;ui.queryError=/Engine 40[45]: (Not Found|Method Not Allowed)$/.test(err.message)?'This engine does not offer the lookup yet.':err.status===404?`${kind==='installation'?'Installation':'Meter reading document'} ${id} does not exist in this run.`:err.message;render();}}
 async function possibleEntries(kind){const m=client(),box=root.querySelector('#ws-f4');if(!m||!box)return;try{const res=await m.possibleEntries(kind==='installation'?'installation':'read',root.querySelector('#ws-query-input')?.value||'');box.innerHTML=`<table class="sap-f4"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody>${(res.rows||res.entries||[]).map(x=>`<tr><td><button type="button" class="fiori-link" data-f4="${e(x.id)}">${e(x.id)}</button></td><td>${e(x.text||x.description||'')}</td></tr>`).join('')||'<tr><td colspan="2">No entries.</td></tr>'}</tbody></table>`;}catch(err){if(!err.superseded)box.innerHTML=`<p class="sap-query-error">${err.status===404||err.status===405?'Possible entries need an engine update.':e(err.message)}</p>`;}}
 // Billing view of an installation (Display Billing) and a meter-reading result (Display Meter Reading Results). Every
 // value is the engine's as of the run date; the screen layout follows Astra's SAP screens.
 function recordPage(){const r=ui.route,isBill=r.tx==='billing',rec=isBill?ui.bill:ui.readDoc;if(!rec||(isBill?rec.installationId:rec.readId)!==r.record)return empty('Loading the record from the engine…');
  const screen=r.screen||(isBill?'orders':'reads'),title=SCREENS[screen]||SCREENS.orders,tabs=isBill?[['orders','Bil. Order'],['periods','Bil.Time'],['documents','Documents']]:[['reads','MR result'],['device','Register']];
  const toolbar=isBill?`${screen!=='orders'?btn('‹ Billing details','screen','data-screen="orders"'):''}${btn('New selection','record-back')}${btn('Installation','screen','data-screen="installation"')}${btn('Contract','screen','data-screen="contract"')}${btn('MR results','screen','data-screen="reads"')}${btn('Show on map','show-map')}`
   :`${ui.readOrigin?btn('‹ Back','read-back'):''}${btn('New selection','record-back')}${btn('Installation','to-billing-query','title="Opens the installation query"')}${rec.case&&!rec.case.resolvedAt?btn('Review / release','read-case'):''}${btn('Show on map','show-map')}`;
  return `<section class="fiori-shell ws-sap-shell">${header(isBill?'billing-query':'read-query',title)}<div class="sap-app ws-sap"><div class="sap-toolbar">${toolbar}<span class="sap-toolbar-rule"></span>${btn('Back to case / list','back')}</div><nav class="sap-tabs" aria-label="Record sections">${tabs.map(([id,l])=>`<button type="button" data-ws="screen" data-screen="${id}" class="${id===screen?'active':''}" ${id===screen?'aria-current="page"':''}>${l}</button>`).join('')}</nav><div class="sap-body">${isBill?billingBody(rec,screen,r.item):readBody(rec,screen)}</div></div>${statusbar(title+' · IS-U / '+(isBill?rec.installationId:rec.installationId||rec.readId))}</section>`;}
 function billingBody(rec,screen,item){
  const acct=(rec.accounts||[])[0]||{},bp=acct.businessPartner||{},contracts=rec.contracts||[],contract=contracts.find(c=>c.current)||contracts[0]||{},docs=[...(rec.billingDocuments||[])].reverse(),invs=[...(rec.invoices||[])].reverse(),reads=[...(rec.reads||[])].reverse(),meters=rec.meters||[];
  const block=(rec.cases||[]).find(c=>!c.resolvedAt&&c.queue==='BILLING'),hold=acct.invoiceHold,cLink=id=>id?sapLink(id,'contract'):'—',status=(ok,text)=>`<span class="sap-square ${ok?'green':''}"></span>${e(text)}`;
  const readLink=r=>`<button type="button" class="sap-link" data-ws="open-read-doc" data-read="${e(r.id)}">${e(day(r.scheduledReadAt||r.readAt))}</button>`;
  if(screen==='orders')return `<h3 class="sap-section-title">Billing Orders</h3>${sapTable(['Installation','Schd MRD','Status','Contract','Short Descript.'],reads.slice(0,12).map(r=>[sapLink(rec.installationId,'installation'),readLink(r),status(r.billStatus==='billed',r.billStatus==='billed'?'Billed':r.billStatus||'Open'),cLink(r.contractId),e(r.readReason==='periodic'?'Periodic billing (01)':r.readReason||'')]),'No meter readings yet in this run.')}<div class="sap-explain">${block?`Billing block · ${e(block.label||block.type)} · clarification case ${e(block.caseId)} (${e(block.category||'')}).`:hold?`Invoicing lock on account ${e(hold.accountId)} since ${day(hold.since)} · ${e(hold.note||'')}.`:'No billing block. The engine bills each released reading and invoices the account on its portion day.'}</div>`;
  if(screen==='periods')return `<h3 class="sap-section-title">Current Billing Periods</h3>${sapTable(['Installation','Contract','Status','Move-in date','Move-out date','Contract account'],contracts.map(c=>[e(rec.installationId),cLink(c.contractId),e(c.status||''),day(c.validFrom),c.validTo?day(c.validTo):'9999-12-31',e(c.accountId)]))}`;
  if(screen==='documents')return `<h3 class="sap-section-title">Billing Documents</h3>${sapTable(['Billing document','Start billing period','End billing period','Contract','Print document','Amount','Status'],docs.map(d=>[sapLink(d.id,'document',d.id),day(d.periodStart),day(d.periodEnd),cLink(d.contractId),d.invoiceId?sapLink(d.invoiceId,'invoice',d.invoiceId):'—',money(d.totalAmount),e([d.billStatus||d.status,d.estimated?'estimated':'',d.reversedAt?'reversed':'',d.version>1?'version '+d.version:''].filter(Boolean).join(' · '))]),'No billing documents yet in this run.')}<h3 class="sap-section-title">Print Documents</h3>${sapTable(['Print document','Issued','Due','Amount','Status','Paid'],invs.map(v=>[sapLink(v.id,'invoice',v.id),day(v.issuedAt),day(v.dueAt),money(v.totalAmount),e(v.invoiceStatus||v.status||''),day(v.paidAt)]),'No invoices yet in this run.')}`;
  if(screen==='contract'){const dun=invs.flatMap(v=>v.dunning||[]).at(0);return `<div class="sap-object"><div>${sapField('Contract',contract.contractId)}${sapField('Installation',rec.installationId,sapLink(rec.installationId,'installation'))}${sapField('Contract Acct',acct.accountId)}</div><div>${sapField('Business partner',bp.name?`${bp.name} · ${bp.businessPartnerId}`:acct.businessPartnerId)}${sapField('SAP contract account',acct.sapContractAccount)}${sapField('Currency',acct.currency)}</div></div><div class="sap-form"><h3>Billing-relevant data</h3>${sapField('Contract status',contract.status)}${sapField('Valid from',day(contract.validFrom))}${sapField('Valid to',contract.validTo?day(contract.validTo):'9999-12-31')}${sapField('Rate category',rec.rateCategory)}${sapField('Billing class',rec.billingClass)}${sapField('Payment method',acct.paymentMethod)}${sapField('Budget billing',acct.budgetBilling?'Yes':'No')}${sapField('Bill.blck.reas.',block?`${block.type} · ${block.label||''}`:'No block')}${sapField('Invoicing Lock',hold?`Clarification hold since ${day(hold.since)}`:'No lock')}${sapField('Last dunning',dun?`${dun.label} · ${day(dun.at)}`:'None')}${sapField('Account balance',money(acct.balance))}</div><h3 class="sap-section-title">Account Ledger</h3>${sapTable(['Posted','Type','Amount','Reference'],[...(acct.ledger||[])].reverse().slice(0,24).map(l=>[day(l.at),e(l.type),money(l.amount),e(l.ref||'')]))}`;}
  if(screen==='installation')return `<div class="sap-object"><div>${sapField('Installation',rec.installationId)}${sapField('Premise',rec.premiseId)}${sapField('Address',rec.address)}</div><div>${sapField('Business partner',bp.name?`${bp.name} · ${bp.businessPartnerId}`:acct.businessPartnerId)}${sapField('Service point',rec.servicePointId)}${sapField('Status',rec.status)}</div></div><div class="sap-form"><h3>General Data</h3>${sapField('Division',rec.division||rec.commodity)}${sapField('Rate Category',rec.rateCategory)}${sapField('Billing class',rec.billingClass)}${sapField('Meter reading unit',rec.mruId)}${sapField('Portion',rec.portion)}</div><h3 class="sap-section-title">Device Data</h3>${sapTable(['Device','Technology','Registers','Units'],meters.map(m=>[sapLink(m.meterId,'device',m.meterId),e(m.technology||''),(m.registers||[]).length,e([...new Set((m.registers||[]).map(x=>x.unit))].join(', '))]))}`;
  if(screen==='device'){const m=meters.find(x=>x.meterId===item)||meters[0]||{};return `<div class="sap-object"><div>${sapField('Device',m.meterId)}${sapField('Installation',rec.installationId,sapLink(rec.installationId,'installation'))}</div></div><div class="sap-form"><h3>IS Data</h3>${sapField('Device category',`${rec.commodity} meter · ${m.technology||''}`)}${sapField('Register group',String((m.registers||[]).length).padStart(3,'0'))}${sapField('Disconn. Status',rec.status==='active'?'Connected':rec.status)}</div><h3 class="sap-section-title">Register Data</h3>${sapTable(['Register','Direction','Unit','Digits','Multiplier'],(m.registers||[]).map(x=>[e(x.registerId),e(x.direction),e(x.unit),x.digits,x.multiplier]))}`;}
  if(screen==='reads')return `<h3 class="sap-section-title">Billing-Relevant Meter-Reading Results</h3>${sapTable(['Schd MR date','MR result','Consumption','MR type','VEE status','Bill status'],reads.map(r=>[readLink(r),num(r.registerValue),r.consumption==null?'—':num(r.consumption)+' '+e(r.unit||''),e(r.readType||''),e(r.veeStatus||''),e(r.billStatus||'')]),'No meter readings yet in this run.')}<div class="sap-explain">Open a scheduled date to display that meter-reading result.</div>`;
  const doc=screen==='document'?docs.find(d=>d.id===item)||docs[0]:null,inv=screen==='invoice'?invs.find(v=>v.id===item)||invs[0]:null;
  if(doc)return `<div class="sap-document-layout"><aside><h3>Document selection</h3>${sapField('Installation',rec.installationId)}<div class="sap-tree"><div>▾ Billing document</div><div>&nbsp; ▾ ${e(doc.id)}</div><div>&nbsp; &nbsp; Header data</div><div>&nbsp; &nbsp; Line items</div></div></aside><section><div class="sap-object">${sapField('Billing document',doc.id)}${sapField('Contract',doc.contractId,cLink(doc.contractId))}${sapField('Contract Acct',doc.accountId)}</div><div class="sap-form"><h3>Header Data</h3>${sapField('Start billing period',day(doc.periodStart))}${sapField('End billing period',day(doc.periodEnd))}${sapField('Billing days',doc.days)}${sapField('Billing transaction',doc.replaces?`Rebill of ${doc.replaces}`:'01 · Periodic')}${sapField('Document status',[doc.billStatus||doc.status,doc.estimated?'estimated':'',doc.reversedAt?'reversed '+day(doc.reversedAt):''].filter(Boolean).join(' · '))}${sapField('Currency',doc.currency)}${sapField('Print document',doc.invoiceId,doc.invoiceId?sapLink(doc.invoiceId,'invoice',doc.invoiceId):'')}</div>${sapTable(['Description','Quantity','Unit','Rate','Amount'],[...(doc.lines||[]).map(l=>[e(l.description||l.type),num(l.quantity),e(l.unit||''),l.rate==null?'—':num(l.rate,4),money(l.amount)]),['Subtotal','','','',money(doc.subtotal)],['Tax','','','',money(doc.tax)],['<b>Total</b>','','','',`<b>${money(doc.totalAmount)}</b>`]])}</section></div>`;
  if(inv)return `<div class="sap-document-layout"><aside><h3>Document selection</h3>${sapField('Contract Acct',inv.accountId)}<div class="sap-tree"><div>▾ Print document</div><div>&nbsp; ▾ ${e(inv.id)}</div><div>&nbsp; &nbsp; Header data</div><div>&nbsp; &nbsp; Payments and dunning</div></div></aside><section><div class="sap-object">${sapField('Print document',inv.id)}${sapField('Contract Acct',inv.accountId)}</div><div class="sap-form"><h3>Header Data</h3>${sapField('Issued',day(inv.issuedAt))}${sapField('Due',day(inv.dueAt))}${sapField('Invoice status',inv.invoiceStatus||inv.status)}${sapField('Amount',money(inv.totalAmount))}${sapField('Paid',day(inv.paidAt))}</div><h3 class="sap-section-title">Billing Documents</h3>${sapTable(['Billing document'],(inv.billingDocumentIds||[]).map(id=>[docs.some(d=>d.id===id)?sapLink(id,'document',id):e(id)]))}<h3 class="sap-section-title">Payments</h3>${sapTable(['Received','Amount','Status'],(inv.payments||[]).map(x=>[day(x.at),money(x.amount),e(x.status||'')]),'No payments.')}<h3 class="sap-section-title">Dunning</h3>${sapTable(['Date','Step'],(inv.dunning||[]).map(x=>[day(x.at),e(x.label||x.type)]),'No dunning.')}</section></div>`;
  return `<div class="sap-explain">No ${screen==='invoice'?'print':'billing'} documents yet for this installation.</div>`;}
 function readBody(rec,screen){const r=rec.read||{},dec=rec.decision||{},unit=r.unit||'';
  const obj=`<div class="sap-object"><div>${sapField('Device',rec.meterId,sapLink(rec.meterId,'device'))}${sapField('Installation',rec.installationId)}${sapField('Register',rec.registerId)}</div><div>${sapField('Scheduled MR date',day(r.scheduledReadAt))}${sapField('MR doc.',rec.readId)}${sapField('Unit of meas.',unit)}</div></div>`;
  if(screen==='device')return `${obj}<div class="sap-form"><h3>IS Data</h3>${sapField('Device category',`${r.commodity||''} meter`)}${sapField('Read source',r.source)}${sapField('Contract',rec.contractId)}${sapField('Contract Acct',rec.accountId)}${sapField('Address',rec.address)}</div><h3 class="sap-section-title">Register Data</h3>${sapTable(['Register','Direction','Unit','Digits','Multiplier'],[[e(rec.registerId),e(r.direction||''),e(unit),r.registerDigits??'—',r.multiplier??'—']])}`;
  const tests=(dec.tests||[]).map(t=>[e(t.test),e(t.outcome),num(t.contribution,3),e(t.rationale)]),c=rec.case,o=rec.order;
  return `${obj}<div class="sap-minitabs"><span class="selected">Page 1</span><span>Values / dates / control</span></div><div class="sap-form"><h3>Meter Reading Result</h3>${sapField('Meter reading',r.registerValue==null?null:num(r.registerValue))}${sapField('Previous reading',r.previousRegisterValue==null?null:num(r.previousRegisterValue))}${sapField('Consumption',r.consumption==null?null:num(r.consumption)+' '+unit)}${sapField('Expected consumption',dec.expectedConsumption==null?null:num(dec.expectedConsumption)+' '+unit)}${sapField('MR type',r.readType)}${sapField('MR status',r.readStatus)}${sapField('MR reason',r.readReason)}${sapField('VEE status',r.veeStatus)}${sapField('VEE confidence',dec.confidence==null?null:Math.round(dec.confidence*100)+'%')}${sapField('Validation code',r.sapValidationCode||dec.sapValidationCode||'None')}${sapField('Bill status',r.billStatus)}</div>${tests.length?`<h3 class="sap-section-title">Validation (VEE)</h3>${sapTable(['Test','Outcome','Risk','Rationale'],tests)}`:''}${c||o?`<h3 class="sap-section-title">Clarification</h3>${sapTable(['Case','Category','Status','Field service order'],[[e(c?.caseId||'—'),e(c?.category||''),e(c?(c.resolvedAt?'Completed':'Open'):''),e(o?`${o.orderId} · ${o.stage}`:'')]])}`:''}<h3 class="sap-section-title">Billing-Relevant Meter-Reading Results</h3>${sapTable(['Schd MR date','MR result','MR type','VEE status'],(rec.history||[]).map(h=>[h.readId===rec.readId?`<b>${day(h.readDate)}</b>`:day(h.readDate),num(h.registerValue),e(h.readType||''),e(h.veeStatus||'')]))}`;}

 // ---- Field service order: Astra's form; the engine owns the order, its stages and its release rules ----------------
 const foSpec=name=>ui.vocab?.order?.fields?.find(f=>f.name===name)||{name,label:name,kind:'text'};
 const foTab=name=>name==='components'?'components':foSpec(name).tab||'header';
 const blankFields=()=>Object.fromEntries((ui.vocab?.order?.fields||[]).map(f=>[f.name,f.kind==='flag'?false:'']));
 function setOrder(o,tab='header'){ui.order={...o,fields:{...blankFields(),...o.fields},components:(o.components||[]).map(c=>({...c})),errors:{},tab};}
 function foField(name,wide=false){const d=ui.order,spec=foSpec(name),value=d.fields[name]??'',err=d.errors[name],id='fo-'+name;
  const attrs=`id="${id}" data-fo-field="${name}" ${d.editable?'':'disabled'} ${spec.required?'aria-required="true"':''} ${err?`aria-invalid="true" aria-describedby="fo-error-${name}"`:''}`;
  const control=spec.kind==='choice'?`<select ${attrs}><option value=""> </option>${(spec.choices||[]).map(v=>`<option ${v===value?'selected':''}>${e(v)}</option>`).join('')}</select>`:spec.kind==='textarea'?`<textarea ${attrs} rows="${name==='longText'?9:4}" maxlength="${spec.maxLength||1600}">${e(value)}</textarea>`:spec.kind==='date'?`<input ${attrs} type="date" value="${e(value)}" min="${e(client()?.asOf||'2026-01-01')}" max="2026-12-31">`:spec.kind==='minutes'?`<input ${attrs} type="number" min="1" max="${spec.maximum||1440}" step="1" value="${e(value)}">`:`<input ${attrs} type="${name==='contactPhone'?'tel':'text'}" maxlength="${spec.maxLength||120}" value="${e(value)}">`;
  return `<div class="fo-field ${wide?'fo-wide':''}"><label for="${id}">${e(FO_LABELS[name]||spec.label)}${spec.required?' <span class="fo-required">*</span>':''}</label>${control}${err?`<small id="fo-error-${name}" class="fo-field-error">${e(err)}</small>`:''}</div>`;}
 const foFlag=name=>`<label><input type="checkbox" data-fo-field="${name}" ${ui.order.fields[name]?'checked':''} ${ui.order.editable?'':'disabled'}> ${e(foSpec(name).label)}</label>`;
 // The release rules, checked here first so the form can point at the fields; the engine checks them again.
 function validateOrder(d){const v=ui.vocab.order,errors={},asOf=client()?.asOf||'',f=d.fields,label=n=>foSpec(n).label,max=foSpec('duration').maximum||1440,units=v.components?.units||['EA','M'];
  for(const n of v.required||[])if(!String(f[n]??'').trim())errors[n]=label(n)+' is required.';
  for(const [n,ch] of Object.entries(v.choices||{}))if(f[n]&&!ch.includes(f[n]))errors[n]='Choose a valid '+label(n).toLowerCase()+'.';
  if(f.startDate&&(!validDay(f.startDate)||f.startDate<asOf||!f.startDate.startsWith('2026')))errors.startDate=`Choose a date in 2026 on or after the run date (${asOf}).`;
  if(f.finishDate&&(!validDay(f.finishDate)||f.finishDate<(f.startDate||'')))errors.finishDate='Finish must be on or after the start date.';
  if(String(f.duration??'')!==''&&!(Number(f.duration)>0&&Number(f.duration)<=max))errors.duration=`Enter a duration from 1 to ${max} minutes.`;
  if(d.components.some(c=>!String(c.description||'').trim()||!(Number(c.quantity)>0)||!units.includes(c.unit)))errors.components='Each component needs a description, a positive quantity and a unit.';
  return errors;}
 function orderPage(){const d=ui.order;if(!d||!ui.vocab)return empty(ui.message||'Loading the field service order from the engine…');
  const ref=d.reference||{},src=d.source||{},stage=d.stage,sys=d.systemStatus||ui.vocab.order.systemStatus?.[stage]||'',asOf=client()?.asOf||'',title=stage==='Draft'?(d.orderId?'Change Field Service Order':'Create Field Service Order'):'Display Field Service Order',units=ui.vocab.order.components?.units||['EA','M'];
  let body='';
  if(d.tab==='header')body=`<div class="fo-columns"><div>${group('Person responsible',foField('plannerGroup')+foField('plant')+foField('workCenter')+foField('responsible')+foField('activityType'))}${group('Dates',foField('startDate')+foField('finishDate')+foField('priority')+`<div class="fo-checks">${foFlag('downtime')}${foFlag('breakdown')}</div>`)}${group('Reference object',field('Installation',ref.installationId)+field('Equipment',ref.meterId)+field('Contract Acct',ref.accountId)+field('Premise',ref.address))}</div><div>${group('Notification Longtext',foField('longText',true))}${group('Source reference',field('Origin',src.kind==='read'?'Implausible meter reading':'Clarification case')+field('Reference',src.kind==='read'?src.readId:src.caseId)+field('Division',ref.commodity)+field('Field Work case',d.caseId||'Created on save'))}</div></div>`;
  if(d.tab==='operations')body=group('First operation',`<div class="fo-operation-number">Operation &nbsp; <span class="gui-code">0010</span></div>${foField('operation')}${foField('duration')}${field('Control key','FIELD')}${field('Work center',d.fields.workCenter||'Not assigned')}`);
  if(d.tab==='components')body=group('Components',`<div class="fo-component-scroll"><table class="fo-components"><thead><tr><th>Item</th><th>Component / description</th><th>Quantity</th><th>Unit</th><th></th></tr></thead><tbody>${d.components.map((c,i)=>`<tr><td>${String((i+1)*10).padStart(4,'0')}</td><td><input aria-label="Component ${i+1}" data-fo-component="${i}" data-fo-key="description" value="${e(c.description??'')}" ${d.editable?'':'disabled'}></td><td><input aria-label="Quantity ${i+1}" type="number" min="1" data-fo-component="${i}" data-fo-key="quantity" value="${e(c.quantity??'')}" ${d.editable?'':'disabled'}></td><td><select aria-label="Unit ${i+1}" data-fo-component="${i}" data-fo-key="unit" ${d.editable?'':'disabled'}>${units.map(u=>`<option ${c.unit===u?'selected':''}>${u}</option>`).join('')}</select></td><td>${btn('Delete','fo-remove-component',`data-index="${i}" ${d.editable?'':'disabled'}`)}</td></tr>`).join('')||'<tr><td colspan="5" class="fo-no-components">No components specified.</td></tr>'}</tbody></table></div>${d.errors.components?`<p class="fo-field-error">${e(d.errors.components)}</p>`:''}<div class="gui-inline-actions">${btn('Add component','fo-add-component',`class="gui-yellow" ${d.editable?'':'disabled'}`)}</div>`);
  if(d.tab==='partner')body=`<div class="fo-columns"><div>${group('Partner',foField('contactName')+foField('contactPhone')+field('Contract Acct',ref.accountId)+field('Service address',ref.address))}</div><div>${group('Access / Dispatch Instructions',foField('accessNotes',true))}</div></div>`;
  const canComplete=stage==='Dispatched'&&asOf>=(d.fields.startDate||'9999');
  const toolbar=`<div class="gui-transaction-toolbar"><button type="submit" data-fo-save="release" ${d.editable?'':'disabled'}>⚑ Release &amp; Save</button><button type="submit" data-fo-save="draft" ${d.editable?'':'disabled'}>▣ Save Draft</button>${btn('Dispatch','fo-dispatch',stage==='Ready for dispatch'?'':'disabled')}${btn('Complete','fo-complete',canComplete?'':`disabled title="${stage==='Dispatched'?`Move the run date to ${e(d.fields.startDate)} or later`:'Dispatch the order first'}"`)}${['Dispatched','Completed'].includes(stage)?btn('Watch the truck roll','fo-watch'):''}${btn('‹ Back to source','fo-back')}</div>`;
  const log=(d.history||[]).length?group('Order history',`<table class="gui-history-table"><thead><tr><th>When</th><th>Status</th></tr></thead><tbody>${d.history.map(h=>`<tr><td>${day(h.at)} ${hm(h.at)}</td><td>${e(h.stage)}</td></tr>`).join('')}</tbody></table>${d.outcome?`<p class="gui-reason-description">Field outcome: ${e(d.outcome)}</p>`:''}`,'gui-history'):'';
  return `<section class="fiori-shell gui-case-shell fo-shell">${header('exceptions',title)}<form id="ws-fo-form" novalidate>${toolbar}<div class="fo-scroll"><div class="fo-order-line">${foField('orderType')}<span class="gui-value fo-order-id">${e(d.orderId||'New')}</span>${foField('shortText')}</div><div class="fo-system-status">Sys.Status <span class="gui-value">${e(sys)} &nbsp; ${e(stage)}</span></div>${Object.keys(d.errors).length?'<div class="fo-validation" role="alert">Complete the highlighted fields before releasing this order for dispatch.</div>':''}<nav class="fo-tabs" aria-label="Order sections">${FO_TABS.map(([id,l])=>`<button type="button" data-fo-tab="${id}" class="${d.tab===id?'active':''}" ${d.tab===id?'aria-current="page"':''}>${l}</button>${d.errors&&Object.keys(d.errors).some(k=>foTab(k)===id)?'<span class="fo-tab-error" aria-hidden="true">!</span>':''}`).join('')}</nav><div class="fo-tab-body">${body}</div>${log}</div></form>${statusbar((d.orderId||'New field service order')+' · '+stage)}</section>`;}
 // Create from a case or a reading: an existing order for that source is reopened, never duplicated.
 async function beginOrder(source,reference){const m=client();if(!m)return;ui.orderReturn=location.hash;
  try{const [vocab,res]=await Promise.all([m.vocabulary(),m.order(source)]);ui.vocab=vocab;if(res.order){setOrder(res.order);go({tx:'field-order',record:res.order.orderId});return;}
   setOrder({orderId:null,stage:'Draft',editable:true,fields:res.proposal||{},components:[],source:{kind:source.readId?'read':'case',caseId:source.sourceCaseId||null,readId:source.readId||null},sourceRef:source,reference,history:[]});go({tx:'field-order',record:'new'});}
  catch(err){if(!err.superseded)toast('Engine: '+err.message);}}
 async function loadOrder(orderId,tab){const m=client();if(!m)return;try{const [vocab,res]=await Promise.all([m.vocabulary(),m.order({orderId})]);ui.vocab=vocab;if(ui.route.tx!=='field-order'||ui.route.record!==orderId)return;if(!res.order){ui.message=`Order ${orderId} is not in this run.`;ui.order=null;}else setOrder(res.order,tab);render();}catch(err){if(!err.superseded){ui.message=err.status===404?`Order ${orderId} is not in this run.`:err.message;ui.order=null;render();}}}
 function orderError(err){const d=ui.order,fe=err.detail?.fieldErrors;if(d&&fe&&Object.keys(fe).length){d.errors=fe;d.tab=foTab(Object.keys(fe)[0]);}toast(err.detail?.message||err.message);render();}
 async function saveOrder(mode){const m=client(),d=ui.order;if(!m||!d?.editable)return;
  if(mode==='release'){d.errors=validateOrder(d);if(Object.keys(d.errors).length){d.tab=foTab(Object.keys(d.errors)[0]);render();return;}}else d.errors={};
  const ref=d.orderId?{orderId:d.orderId}:d.sourceRef,fields={...d.fields},components=d.components.map(c=>({description:c.description??'',quantity:c.quantity===''||c.quantity==null?'':Number(c.quantity),unit:c.unit}));if(fields.duration!==''&&fields.duration!=null)fields.duration=Number(fields.duration);
  try{await m.act('order_save',null,null,{...ref,fields,components});}catch(err){if(!err.superseded)orderError(err);return;}
  let o;try{o=(await m.order(ref)).order;}catch(err){if(!err.superseded)toast('Engine: '+err.message);return;}
  if(mode==='release'){try{await m.act('order_release',null,null,{orderId:o.orderId});o=(await m.order({orderId:o.orderId})).order;toast(`${o.orderId} released and ready for dispatch.`);}catch(err){if(err.superseded)return;setOrder(o,d.tab);ui.route={tx:'field-order',record:o.orderId};go(ui.route);orderError(err);return;}}
  else toast(`${o.orderId} saved as a draft. Complete the form before release.`);
  setOrder(o,d.tab);go({tx:'field-order',record:o.orderId});if(location.hash===workspaceHash({tx:'field-order',record:o.orderId}))render();}
 async function orderStep(type,extra={}){const m=client(),d=ui.order;if(!m||!d?.orderId)return;try{await m.act(type,null,null,{orderId:d.orderId,...extra});const o=(await m.order({orderId:d.orderId})).order;setOrder(o,d.tab);toast(`${o.orderId}: ${o.stage}.`);render();}catch(err){if(!err.superseded)orderError(err);}}
 // A short form for notes, holds, releases and field outcomes; resolves to the text, or null when cancelled.
 function ask(title,{label='Note',submit='Save',required=true,text=''}={}){return new Promise(resolve=>{let dlg=document.getElementById('ws-dialog');if(!dlg){dlg=document.createElement('dialog');dlg.id='ws-dialog';dlg.className='ws-dialog';document.body.append(dlg);}
  dlg.innerHTML=`<form class="clarification-action-form"><div class="dialog-head"><h2>${e(title)}</h2><button type="button" data-close aria-label="Close dialog">×</button></div>${text?`<p>${e(text)}</p>`:''}<label>${e(label)}<textarea name="note" rows="3" maxlength="2000" ${required?'required':''} placeholder="Record the decision or next action"></textarea></label><div class="read-review-actions"><button type="submit">${e(submit)}</button><button type="button" data-close>Cancel</button></div><p class="small">Recorded as an engine action on the run date (${e(client()?.asOf||'')}).</p></form>`;
  let settled=false;const done=v=>{if(settled)return;settled=true;if(dlg.open)dlg.close();resolve(v);};dlg.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>done(null));dlg.querySelector('form').onsubmit=ev=>{ev.preventDefault();const v=dlg.querySelector('textarea').value.trim();if(required&&!v)return;done(v);};dlg.oncancel=()=>done(null);dlg.showModal();dlg.querySelector('textarea').focus();});}
 async function caseAction(c,type,extra={},message){const m=client();try{await m.act(type,c.caseId,null,extra);toast(message||`${c.caseId}: ${type.replace('_',' ')} recorded on ${m.asOf}.`);loadCase(c.caseId);loadCounts();}catch(err){if(!err.superseded)toast(err.detail?.message||err.message);}}

 // ---- rendering and events --------------------------------------------------------------------------------------
 function render(){const m=client();if(!root)return;if(!m){root.innerHTML=`<section class="fiori-shell"><div class="fiori-empty ws-empty"><h2>Workspace needs the engine</h2><p>Open an engine town (for example <code>?town=ayr</code>), or run <code>uv run utilsim serve</code> locally and add <code>?engine=http://127.0.0.1:8010</code>.</p></div></section>`;return;}
  const r=ui.route;let html;
  if(r.caseId)html=ui.caseView&&ui.caseView.caseId===r.caseId?casePage(ui.caseView):empty(ui.message||'Loading the case from the engine…');
  else if(r.tx==='vee')html=veePage();
  else if(r.tx==='billing-query')html=queryPage('installation');
  else if(r.tx==='read-query')html=queryPage('read');
  else if(r.tx==='billing'||r.tx==='reads')html=recordPage();
  else if(r.tx==='statistics')html=statisticsPage();
  else if(r.tx==='field-order')html=orderPage();
  else html=casesPage();
  root.innerHTML=html;
 }
 function open(hash){const r=parseWorkspaceRoute(hash);ui.message='';
  // Record pages need the matching executed query in this session; otherwise return to the query.
  if(r.tx==='billing'&&!has('installation',r.record)){go({tx:'billing-query'});return;}
  if(r.tx==='reads'&&!has('read',r.record)){go({tx:'read-query'});return;}
  // A new order exists only in this session until it is saved; without it, go back to the list.
  if(r.tx==='field-order'&&r.record==='new'&&(!ui.order||ui.order.orderId)){go({tx:'exceptions'});return;}
  if(r.tx==='field-order'&&r.record!=='new'&&ui.order?.orderId!==r.record){ui.order=null;loadOrder(r.record);}
  ui.route=r;render();
  if(r.caseId)loadCase(r.caseId);else if(r.tx==='vee')loadVee();else if(r.tx==='statistics')loadSummary();else if(r.tx==='exceptions'){loadCases();loadCounts();}
 }
 root?.addEventListener('change',ev=>{const t=ev.target;
  if(t.id==='ws-transaction'&&t.value){ui.queryError='';go({tx:t.value});}
  else if(t.id==='ws-status'){ui.status=t.value;loadCases();}
  else if(t.id==='ws-vee-view'){ui.veeStatus=t.value;ui.selected.clear();loadVee();}
  else if(t.id==='ws-vee-utility'){ui.veeUtility=t.value;render();}
  else if(t.dataset.readSelect){if(t.checked)ui.selected.add(t.dataset.readSelect);else ui.selected.delete(t.dataset.readSelect);render();}
  else if(t.id==='ws-select-all'){const open=veeRows().filter(r=>!r.resolvedAt);if(t.checked)open.forEach(r=>ui.selected.add(r.caseId));else ui.selected.clear();render();}
  else if(t.id==='ws-asof'&&t.value){const m=client();m.setAsOf(t.value);toast(`Run date ${t.value}: actions are recorded on this day.`);if(ui.route.tx==='field-order'&&ui.order?.orderId)loadOrder(ui.order.orderId,ui.order.tab);open(location.hash);}
  else if(t.dataset.foField||t.dataset.foComponent!=null)captureOrder(t);
 });
 function captureOrder(t){const d=ui.order;if(!d?.editable)return;if(t.dataset.foField){d.fields[t.dataset.foField]=t.type==='checkbox'?t.checked:t.value;delete d.errors[t.dataset.foField];}else{const c=d.components[Number(t.dataset.foComponent)];if(c&&['description','quantity','unit'].includes(t.dataset.foKey)){c[t.dataset.foKey]=t.value;delete d.errors.components;}}}
 root?.addEventListener('input',ev=>{const t=ev.target;if(t.dataset.foField||t.dataset.foComponent!=null){captureOrder(t);return;}if(t.id==='ws-query'){ui.query=t.value;const body=root.querySelector('#ws-cases');if(body){body.innerHTML=caseBody();root.querySelector('#ws-count').textContent=caseRows().length+' cases';}}else if(t.id==='ws-vee-query'){ui.veeQuery=t.value;}});
 root?.addEventListener('submit',ev=>{const f=ev.target;if(f.id==='ws-query-form'){ev.preventDefault();execute(f.dataset.kind,f.q.value);}else if(f.id==='ws-fo-form'){ev.preventDefault();saveOrder(ev.submitter?.dataset.foSave||'draft');}});
 root?.addEventListener('click',async ev=>{
  const cat=ev.target.closest('[data-category]');if(cat){if(cat.dataset.category==='MR Implausibles'){go({tx:'vee'});return;}ui.category=cat.dataset.category;render();loadCases();return;}
  const row=ev.target.closest('[data-case]:not([data-ws])');if(row&&row.tagName==='TR'){go({caseId:row.dataset.case});return;}
  const f4=ev.target.closest('[data-f4]');if(f4){const input=root.querySelector('#ws-query-input');input.value=f4.dataset.f4;ui.queries[root.querySelector('#ws-query-form').dataset.kind]=f4.dataset.f4;root.querySelector('#ws-f4').innerHTML='';input.focus();return;} // F4 selects; Execute is still needed
  const tab=ev.target.closest('[data-fo-tab]');if(tab&&ui.order){ui.order.tab=tab.dataset.foTab;render();return;}
  const b=ev.target.closest('[data-ws]');if(!b||b.disabled)return;const act=b.dataset.ws,m=client(),c=ui.route.caseId?ui.caseView:null;
  if(act==='layout'){ui.compact=!ui.compact;render();}
  else if(act==='refresh'){loadCases();loadCounts();}
  else if(act==='statistics')go({tx:'statistics'});
  else if(act==='scorecard'){if(ui.scorecard){ui.scorecard=null;render();return;}ui.scorecard=true;render();try{ui.scorecard=await m.scorecard();}catch(err){ui.scorecard=null;if(!err.superseded)toast('Engine: '+err.message);}render();}
  else if(act==='watch'&&c?.fieldVisits?.length){const v=c.fieldVisits[0];onWatch({caseId:c.caseId,premiseId:c.premiseId,day:v.day,seconds:v.seconds});}
  else if(act==='sort'){ui.sort=ui.sort==='age'?'case':'age';loadCases();}
  else if(act==='export-cases')exportCsv(caseRows());
  else if(act==='filters'){ui.filters=!ui.filters;render();}
  else if(act==='clear-vee'){ui.veeUtility='all';ui.veeQuery='';render();}
  else if(act==='release-reads')releaseSelected('accept');
  else if(act==='estimate-reads')releaseSelected('estimate');
  else if(act==='open-read')go({caseId:b.dataset.case});
  else if(act==='back')go({tx:'exceptions'});
  else if(act==='history'){ui.historyOpen=!ui.historyOpen;render();}
  else if(act==='billing-query')go({tx:'billing-query'});
  else if(act==='f4')possibleEntries(b.dataset.kind);
  else if(act==='record-back')go({tx:ui.route.tx==='billing'?'billing-query':'read-query'});
  else if(act==='screen'){const {item,...rest}=ui.route;go({...rest,screen:b.dataset.screen,...(b.dataset.item?{item:b.dataset.item}:{})});}
  else if(act==='open-read-doc'){const id=b.dataset.read;try{ui.readDoc=await m.readDocument(id);ui.context.read=id;ui.readOrigin={tx:'billing',record:ui.bill.installationId,screen:'reads'};go({tx:'reads',record:id});}catch(err){if(!err.superseded)toast(err.status===404?`Meter reading document ${id} is not available on ${m.asOf}.`:'Engine: '+err.message);}}
  else if(act==='read-back'&&ui.readOrigin)go(ui.readOrigin);
  else if(act==='to-billing-query'){ui.queries.installation=ui.readDoc?.installationId||'';ui.queryError='';go({tx:'billing-query'});}
  else if(act==='read-case'&&ui.readDoc?.case)go({caseId:ui.readDoc.case.caseId});
  else if(act==='show-map'){const r=ui.route,id=r.caseId?c?.premiseId:r.tx==='billing'?ui.bill?.premiseId:r.tx==='reads'?ui.readDoc?.premiseId:r.tx==='field-order'?ui.order?.reference?.premiseId:null;if(id)onShowPremise(id);}
  else if(act==='assign'&&c)caseAction(c,'assign',{assignee:'you'},`${c.caseId} is yours: automation leaves it to you.`);
  else if(act==='note'&&c){const text=await ask('Case note / resolution',{text:`${c.label} · ${c.caseId}`,submit:'Save note'});if(text)caseAction(c,'note',{text},`${c.caseId}: note saved.`);}
  else if(act==='hold'&&c){const note=await ask('Do Not Invoice Account',{label:'Reason',text:`Account ${c.accountId}: invoices wait until the hold is removed.`,submit:'Hold account'});if(note)caseAction(c,'invoice_hold',{note},`Account ${c.accountId} is on invoice hold.`);}
  else if(act==='unhold'&&c){const note=await ask('Remove Invoice Hold',{label:'Reason',text:`Account ${c.invoiceHold?.accountId||c.accountId}`,submit:'Remove hold'});if(note)caseAction(c,'invoice_unhold',{note},'Invoice hold removed.');}
  else if(act==='release-outsort'&&c){const note=await ask('Release billing / invoice outsort',{label:'Release reason',text:`${c.label} · ${c.caseId}`,submit:'Release outsort'});if(note)caseAction(c,'accept',{note},`${c.caseId}: outsort released.`);}
  else if(act==='field-order'&&c)beginOrder({sourceCaseId:c.caseId},{premiseId:c.premiseId,address:c.address,accountId:c.accountId,meterId:c.meterId||c.read?.meterId,installationId:c.read?.installationId,commodity:c.commodity});
  else if(act==='vee-order'){const r=ui.veeRows.find(x=>ui.selected.has(x.caseId)&&!x.resolvedAt);if(r){ui.selected.clear();beginOrder({readId:r.readId},{premiseId:r.premiseId,address:r.address,accountId:r.accountId,meterId:r.meterId,commodity:r.commodity});}}
  else if(act==='open-order'){const id=b.dataset.order||c?.order?.orderId||c?.orders?.[0]?.orderId;if(id){ui.orderReturn=location.hash;go({tx:'field-order',record:id});}}
  else if(act==='fo-add-component'&&ui.order?.editable){ui.order.components.push({description:'',quantity:1,unit:(ui.vocab?.order?.components?.units||['EA'])[0]});render();}
  else if(act==='fo-remove-component'&&ui.order?.editable){ui.order.components.splice(Number(b.dataset.index),1);delete ui.order.errors.components;render();}
  else if(act==='fo-dispatch')orderStep('order_dispatch');
  else if(act==='fo-complete'){const note=await ask('Complete field work',{label:'Field outcome',text:`${ui.order.orderId} · ${ui.order.fields.shortText||''}`,submit:'Complete work'});if(note)orderStep('order_complete',{note});}
  else if(act==='fo-watch'&&ui.order){const d=ui.order;onWatch({caseId:d.caseId,premiseId:d.reference?.premiseId,day:d.fields.startDate,seconds:7*3600});}
  else if(act==='fo-back'){const src=ui.order?.source;location.hash=ui.orderReturn||(src?.caseId?workspaceHash({caseId:src.caseId}):workspaceHash({tx:'exceptions'}));}
  else if(act==='trace'&&c)onProcess(c);
  else if(['accept','estimate','escalate'].includes(act)&&c){try{await m.act(act,c.caseId);toast(`${c.caseId}: ${act} recorded on ${m.asOf}.`);loadCase(c.caseId);}catch(err){if(!err.superseded)toast(err.message);}}
  else if(act==='override'&&c){const v=prompt('Corrected register value',c.read?.registerValue??'');if(v==null||v==='')return;try{await m.act('override',c.caseId,v);toast(`${c.caseId}: corrected value recorded.`);loadCase(c.caseId);}catch(err){if(!err.superseded)toast(err.message);}}
 });
 function exportCsv(rows){const head=['caseId','category','label','address','accountId','queue','assignee','ageDays','impact'],csv=[head.join(','),...rows.map(r=>head.map(k=>JSON.stringify(k==='category'?categoryOf(r):r[k]??'')).join(','))].join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='clarification-cases.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 return {open,render,get state(){return ui;}};
}
